import json,glob,collections
c=collections.Counter()
for f in glob.glob('poe/poe-report-dashboard/logs/**/*.jsonl',recursive=True):
    for line in open(f):
        try: r=json.loads(line)
        except: continue
        m=r.get('message') or {}
        cont=m.get('content') if isinstance(m,dict) else None
        if isinstance(cont,list):
            for b in cont:
                if isinstance(b,dict) and b.get('type') in('thinking','redacted_thinking'):
                    t=b.get('thinking','')
                    c[(b['type'],'empty' if not t else 'text',tuple(sorted(b.keys())))]+=1
print(c)
EOF
