python3 - <<'EOF'
import json,glob,collections
for f in sorted(glob.glob('poe/poe-report-dashboard/logs/**/*.jsonl',recursive=True)):
    c=collections.Counter(); models=set(); ver=set()
    for line in open(f):
        try: r=json.loads(line)
        except: continue
        if r.get('version'): ver.add(r['version'])
        m=r.get('message') or {}
        if isinstance(m,dict) and m.get('model'): models.add(m['model'])
        cont=m.get('content') if isinstance(m,dict) else None
        if isinstance(cont,list):
            for b in cont:
                if isinstance(b,dict) and b.get('type')=='thinking':
                    c['text' if b.get('thinking') else 'empty']+=1
    print(f.split('logs/')[1][:60], dict(c), models, ver)
EOF
