input.command:
git status --short && git diff --stat && PYTHONDONTWRITEBYTECODE=1 python3 -m unittest discover tests 2>&1 | tail -3 && python3 - <<'EOF'
import json,glob
n=t=0
for f in glob.glob('poe/poe-report-dashboard/logs/**/*.jsonl',recursive=True):
    for l in open(f):
        try: r=json.loads(l)
        except: continue
        if r.get('type')!='assistant': continue
        for b in r['message'].get('content',[]):
            if isinstance(b,dict) and b.get('type')=='thinking':
                n+=1; t+=bool(b.get('thinking'))
print('assistant thinking blocks',n,'with text',t)
EOF
